<template>
  <div>
    <ion-page>
      <ion-header>
        <ion-toolbar>
          <ion-title style="font-size: 25px; font-weight: 600"
            >Reject Test</ion-title
          >
          <ion-buttons slot="end">
            <ion-button :strong="true" @click="handleDialog">
              <ion-icon size="large" :icon="close"></ion-icon>
            </ion-button>
          </ion-buttons>
        </ion-toolbar>
      </ion-header>
      <ion-content>
        <ion-list>
          <ion-item>
            <ion-label style="font-size: 20px; font-weight: 600"
              >Test Type</ion-label
            >
            <ion-label slot="end" style="font-size: 18px;">{{ testDisplayName }}</ion-label>
          </ion-item>
          <ion-item>
            <ion-label style="font-size: 20px; font-weight: 600"
              >Specimen</ion-label
            >
            <ion-label slot="end" style="font-size: 18px;">{{ details?.specimen_type }}</ion-label>
          </ion-item>
          <ion-item>
            <ion-label style="font-size: 20px; font-weight: 600"
              >Patient Name</ion-label
            >
            <ion-label slot="end" style="font-size: 18px;">
                {{ details?.client ?
                    `${details.client.first_name} ${details.client.middle_name ? details.client.middle_name : ''} ${details.client.last_name}` :
                    ''
                }}
              </ion-label>

          </ion-item>
          <ion-item>
            <ion-label style="font-size: 20px; font-weight: 600"
              >Accession Number</ion-label
            >
            <ion-label slot="end" style="font-size: 18px;">{{ details?.accession_number }}</ion-label>
          </ion-item>
          <ion-item>
            <ion-label style="font-size: 20px; font-weight: 600"
              >Person Talked To:
            </ion-label>
            <ion-input
              v-model="personTalkedTo"
              required
              placeholder="Enter full name"
              @ion-focus="enterInput('person')"
              style="font-size: 18px;"
            />
          </ion-item>

          <ion-item>
            <ion-label style="font-size: 20px; font-weight: 600"
              >Rejection Reason:
            </ion-label>
            <ion-select required v-model="selectedStatusReason">
              <ion-select-option
                v-for="reason in statusReasons"
                v-bind:key="reason.description"
                :value="reason.description"
                style="font-size: 18px;"
                >{{ reason.description }}</ion-select-option
              >
              <ion-select-option :value="OTHER_OPTION" style="font-size: 18px;"
                >Other (enter manually)</ion-select-option
              ></ion-select
            >
          </ion-item>

          <ion-item v-if="selectedStatusReason === OTHER_OPTION">
            <ion-label
              position="stacked"
              style="font-size: 20px; font-weight: 600"
              >Specify Reason:</ion-label
            >
            <ion-textarea
              v-model="otherReason"
              :auto-grow="true"
              required
              placeholder="Type the reason in full"
              @ion-focus="enterInput('reason')"
              style="font-size: 18px;"
            />
          </ion-item>

          <ion-item
            v-if="selectedStatusReason === OTHER_OPTION && reasonSuggestions.length"
            lines="none"
          >
            <div>
              <p
                style="font-size: 15px; color: var(--ion-color-medium); margin: 4px 0;"
              >
                Similar existing reasons &mdash; tap to use one:
              </p>
              <ion-chip
                v-for="suggestion in reasonSuggestions"
                :key="suggestion"
                color="success"
                outline
                @click="applySuggestion(suggestion)"
              >
                <ion-label>{{ suggestion }}</ion-label>
              </ion-chip>
            </div>
          </ion-item>
        </ion-list>
        <div class="keyboard" v-show="showKeyboard">
          <SimpleKeyboard
            @onChange="onChange"
            @onKeyPress="onKeyPress"
            :input="focusedField === 'reason' ? otherReason : personTalkedTo"
            :inputName="focusedField === 'reason' ? otherReason : personTalkedTo"
          />
        </div>
      </ion-content>

      <ion-footer>
        <ion-toolbar color="light" style="padding: 5px">
          <ion-button
            slot="start"
            size="large"
            color="danger"
            @click="cancelReject"
          >
            Cancel
          </ion-button>
          <ion-button
            slot="end"
            :disabled="!isset"
            size="large"
            color="success"
            @click="submitForm"
          >
            Reject
          </ion-button>
        </ion-toolbar></ion-footer
      >
    </ion-page>
  </div>
</template>

<script setup lang="ts">
import { Client } from "@/composables/client";
import { useTestNamePreference } from "@/composables/testNamePreference";
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { close } from "ionicons/icons";
import { alertConfirmation, toastSuccess } from "@/utils/Alerts";
import {
  IonButtons,
  IonButton,
  IonIcon,
  IonHeader,
  IonContent,
  IonToolbar,
  IonTitle,
  IonItem,
  IonLabel,
  IonFooter,
  IonList,
  IonPage,
  IonSelect,
  IonSelectOption,
  IonInput,
  IonTextarea,
  IonChip,
} from "@ionic/vue";
import SimpleKeyboard from "@/components/Keyboard/SimpleKeyBoard.vue";

// Sentinel option that reveals the free-text reason field.
const OTHER_OPTION = "Other";

const route = useRoute();
const router = useRouter();
const client = Client();
const { getDisplayName } = useTestNamePreference();
const details = ref<any>({});
const personTalkedTo = ref<string>("");
const statusReasons = ref<Array<{ id: number; description: string }>>([]);
const selectedStatusReason = ref("");
const otherReason = ref<string>("");
const focusedField = ref<"person" | "reason">("person");

// Existing reasons that share a word (>= 4 characters) with the free text being
// typed, ranked by number of matching words - lets the user reuse an existing
// reason instead of creating a near-duplicate.
const reasonSuggestions = computed<string[]>(() => {
  const words = otherReason.value
    .toLowerCase()
    .split(/\s+/)
    .filter((word) => word.length >= 4);
  if (!words.length) return [];

  const typed = otherReason.value.trim().toLowerCase();
  return statusReasons.value
    .map((reason) => {
      const description = (reason.description || "").toLowerCase();
      const hits = words.filter((word) => description.includes(word)).length;
      return { description: reason.description, hits };
    })
    .filter((reason) => reason.hits > 0 && reason.description.toLowerCase() !== typed)
    .sort((a, b) => b.hits - a.hits)
    .slice(0, 6)
    .map((reason) => reason.description);
});

const applySuggestion = (description: string) => {
  selectedStatusReason.value = description;
  otherReason.value = "";
};

const testDisplayName = computed(() =>
  getDisplayName(details.value?.test_type_name, details.value?.test_type_preferred_name)
);

const getTest = async () => {
  const res = await client.getJson(`/tests/${route.params.id}`);
  details.value = res?.data;
};

const handleDialog = () => {
  router.back();
};

const cancelReject = async () => {
  const ok = await alertConfirmation("Are you sure you want to cancel?");
  if (ok) handleDialog();
};

const emits = defineEmits(["updated"]);

const showKeyboard = ref<boolean>(false);

const enterInput = (value: "person" | "reason") => {
  focusedField.value = value;
  showKeyboard.value = true;
};

const onChange = (input: string) => {
  if (focusedField.value === "reason") {
    otherReason.value = input;
  } else {
    personTalkedTo.value = input;
  }
};

const onKeyPress = (input: string) => {
  if (input == "{enter}") {
    showKeyboard.value = false;
  }
};

const getStatusReasons = async () => {
  const res = await client.getJson("status_reasons");
  statusReasons.value = res?.data;
};
const isset = computed(() => {
  if (!personTalkedTo.value) return false;
  if (selectedStatusReason.value === OTHER_OPTION) {
    return !!otherReason.value.trim();
  }
  return !!selectedStatusReason.value;
});

const submitForm = async () => {
  const isOther = selectedStatusReason.value === OTHER_OPTION;
  const otherText = otherReason.value.trim();

  // Resolve to an existing reason id where possible: a normal selection, or an
  // "Other" reason the user typed that already exists (case-insensitive).
  let reasonId: number | null = null;
  const lookup = isOther ? otherText.toLowerCase() : selectedStatusReason.value;
  for (const status of statusReasons.value) {
    const description = isOther
      ? (status.description || "").trim().toLowerCase()
      : status.description;
    if (description === lookup) {
      reasonId = status.id;
      break;
    }
  }

  const params = new URLSearchParams();
  params.set("person_talked_to", personTalkedTo.value);
  if (isOther && reasonId === null) {
    // Brand-new free-text reason: the API creates it, then proceeds as normal.
    params.set("other_reason", otherText);
  } else {
    params.set("status_reason_id", String(reasonId ?? ""));
  }

  const res = await client.putJson(
    `test_statuses/${route.params.id}/rejected?${params.toString()}`,
    {}
  );
  if (res?.data) {
    toastSuccess("Test Rejected Successfully");
    router.push("/tests");
    emits("updated", true);
  }
};
onMounted(() => {
  getTest();
  getStatusReasons();
});
</script>

<style scoped>
.keyboard {
  width: 100%;
  bottom: 0;
  position: absolute !important;
  font-size: 30px;
  text-transform: uppercase;
  font-weight: 400;
}
</style>
